DE_REST_C1 = {
    ('Text/Event/Miyako/Ekken.csvtxt', 'English#c:04010201_0'): 'Das ist alles. Alles verläuft reibungslos,\nund die Sicherheit der Hauptstadt wird unerschütterlich sein,\nwenn die Vollendung anbricht.',
    ('Text/Event/Miyako/Ekken.csvtxt', 'English#c:04010201_1'): 'Alles werde geschehen, wie ihr es wünscht, Lady Kamuhitsuki.',
    ('Text/Event/Miyako/Ekken.csvtxt', 'English#c:04010201_10'): 'Ihr dürft treten. Es ist Zeit für meine Mahlzeit.\nIch freue mich auf die Verehrten Ähren, die\nPrinzessin Sakuna in letzter Zeit geschickt hat!',
    ('Text/Event/Miyako/Ekken.csvtxt', 'English#c:04010201_11'): 'Die Marke wird in der ganzen Hauptstadt geschätzt.',
    ('Text/Event/Miyako/Ekken.csvtxt', 'English#c:04010201_12'): 'Wenn wir uns im Reichtum schwelgen, reicht diese\nFülle selbst bis ins Niedrige Reich.\nSo ist das Werk der Götter.',
    ('Text/Event/Miyako/Ekken.csvtxt', 'English#c:04010201_13'): 'Sakunas...? Hmmm...',
    ('Text/Event/Miyako/Ekken.csvtxt', 'English#c:04010201_14'): 'Lady Kamuhitsuki. Ich bitte um Verzeihung, aber da ist\nnoch etwas, das ich testen möchte.',
    ('Text/Event/Miyako/Ekken.csvtxt', 'English#c:04010201_2'): 'Großartige Arbeit, Prinzessin Kokorowa.\nDein Bericht hat meine Erwartungen übertroffen.',
    ('Text/Event/Miyako/Ekken.csvtxt', 'English#c:04010201_3'): 'Auch die anderen Götter preisen dich.\nVon nun an überlasse ich diese Angelegenheit\nvollständig in deine Hände.',
    ('Text/Event/Miyako/Ekken.csvtxt', 'English#c:04010201_4'): 'Solltest du Mittel oder Ressourcen benötigen,\nkannst du sie ohne Zögern anfordern.',
    ('Text/Event/Miyako/Ekken.csvtxt', 'English#c:04010201_5'): 'Ja, meine Herrin. Mein Dank ist grenzenlos.',
    ('Text/Event/Miyako/Ekken.csvtxt', 'English#c:04010201_6'): 'Trotzdem, zu denken, dass solch ein Feingefühl\nin dir verborgen war...',
    ('Text/Event/Miyako/Ekken.csvtxt', 'English#c:04010201_7'): 'Hast du dich die ganze Zeit im Schatten\njemandes anderen verkrochen gehalten?',
    ('Text/Event/Miyako/Ekken.csvtxt', 'English#c:04010201_8'): 'Nein, meinen früheren Eindruck kann ich\nnichts anderem als meinen eigenen Mängeln zuschreiben.',
    ('Text/Event/Miyako/Ekken.csvtxt', 'English#c:04010201_9'): 'Ich verstehe. Alles hat sich zum Guten gewendet,\nalso kann ich deinem Wachstum kaum widersprechen.',
    ('Text/Event/Miyako/Ekken.csvtxt', 'English#c:04010405_0'): 'Was ist das für ein duftender Geruch?',
    ('Text/Event/Miyako/Ekken.csvtxt', 'English#c:04010501_0'): 'Prinzessin Sakuna, du bist ungebeten zurückgekehrt,\nnachdem ich dich auf die Insel der Dämonen verbannt habe.',
    ('Text/Event/Miyako/Ekken.csvtxt', 'English#c:04010501_1'): 'Überdies hast du unseren göttlichen Speicher\nnicht einmal, sondern zweimal vernichtet.',
    ('Text/Event/Miyako/Ekken.csvtxt', 'English#c:04010501_10'): 'Neid riss mich in seinen heimtückischen Griff,\nund ich besudelte meine Hände mit bösen Taten.',
    ('Text/Event/Miyako/Ekken.csvtxt', 'English#c:04010501_11'): 'Bitte... vergib mir!',
    ('Text/Event/Miyako/Ekken.csvtxt', 'English#c:04010501_12'): 'Meine Güte, solch eine Aufrichtigkeit.',
    ('Text/Event/Miyako/Ekken.csvtxt', 'English#c:04010501_13'): 'Deine Arbeit hat in letzter Zeit erhebliche\nAufmerksamkeit erregt, was dies alles\nnoch enttäuschender macht.',
    ('Text/Event/Miyako/Ekken.csvtxt', 'English#c:04010501_14'): 'Denk nicht, du entkommst der ultimativen Strafe-- Hm?',
    ('Text/Event/Miyako/Ekken.csvtxt', 'English#c:04010501_15'): 'Hmmm? Wir dürfen Prinzessin Kokorowa nicht verlieren?\nUnd nicht nur, weil wir die mechanischen Soldaten\nnicht mehr weiterproduzieren können?',
    ('Text/Event/Miyako/Ekken.csvtxt', 'English#c:04010501_16'): 'Ich werde von Anfragen überflutet, wenn ich unmittelbar\nnach diesem Aufruhr über eine so wichtige,\nhochgestellte Göttin urteile?',
    ('Text/Event/Miyako/Ekken.csvtxt', 'English#c:04010501_17'): 'Gerüchte werden Gerüchte gebären, bis die anderen Götter\nvon den mechanischen Soldaten erfahren und Chaos stiften?\nDas... entspräche nicht meinen Bedürfnissen.',
    ('Text/Event/Miyako/Ekken.csvtxt', 'English#c:04010501_18'): 'Ich würde zur Blüte der Schande aufsteigen, wenn es\nverlautete, dass ich in meiner Verliebtheit\nunwissentlich einen Speicher für giftigen Reis baute.',
    ('Text/Event/Miyako/Ekken.csvtxt', 'English#c:04010501_19'): 'Sicherlich, als überragende Göttin\nwird meine mühevoll errungene Ehre...',
    ('Text/Event/Miyako/Ekken.csvtxt', 'English#c:04010501_2'): 'Hast du etwas zu deiner Rechtfertigung zu sagen?',
    ('Text/Event/Miyako/Ekken.csvtxt', 'English#c:04010501_20'): '*hust* Prinzessin Kokorowa. Für deine Mitschuld an solch\neiner Zwietracht würdest du normalerweise\nzum Tode verurteilt.',
    ('Text/Event/Miyako/Ekken.csvtxt', 'English#c:04010501_21'): 'Jedoch, in Anbetracht deiner\nErfolge und deiner tiefen Freundschaft mit\nPrinzessin Sakuna, vergebe ich dir dieses eine Mal.',
    ('Text/Event/Miyako/Ekken.csvtxt', 'English#c:04010501_22'): 'Ich danke demütigst für deine Nachsicht.\nMeine Seele bebt vor Dankbarkeit!',
    ('Text/Event/Miyako/Ekken.csvtxt', 'English#c:04010501_23'): 'Also ist auch Lady Kamuhitsuki weniger gelassen,\nals sie auf den ersten Blick wirkt...',
    ('Text/Event/Miyako/Ekken.csvtxt', 'English#c:04010501_24'): 'Deshalb... Kommen wir erneut zu dir, Prinzessin Sakuna...',
    ('Text/Event/Miyako/Ekken.csvtxt', 'English#c:04010501_25'): 'Dir ist von nun an gestattet, wann immer du möchtest\nin die Hauptstadt zurückzukehren.',
    ('Text/Event/Miyako/Ekken.csvtxt', 'English#c:04010501_26'): 'Ich widerrufe den Erlass bezüglich der\nInsel der Dämonen nicht, aber du kannst hier ruhen,\nwenn dich deine Mühen ermüden.',
    ('Text/Event/Miyako/Ekken.csvtxt', 'English#c:04010501_27'): 'Ja, meine Herrin!',
    ('Text/Event/Miyako/Ekken.csvtxt', 'English#c:04010501_3'): 'Es leid tut es mir zu berichten, dass der Speicher\neine Variante meiner Verehrten Ähren enthielt, die hochgradig giftig war.',
    ('Text/Event/Miyako/Ekken.csvtxt', 'English#c:04010501_4'): 'Ich hatte keine Wahl, als mich hierher zu beeilen\nund sicherzustellen, dass er euren göttlichen Gaumen nicht verseuchte.',
    ('Text/Event/Miyako/Ekken.csvtxt', 'English#c:04010501_5'): 'Ich wage zu sagen: Wenn meine frühere Explosion\neine Tragödie war, dann ist diese hier ein Sieg!\nHorch, es ist der entzündbare Duft der Tugend!',
    ('Text/Event/Miyako/Ekken.csvtxt', 'English#c:04010501_6'): 'Ich verstehe kein einziges Wort.',
    ('Text/Event/Miyako/Ekken.csvtxt', 'English#c:04010501_7'): 'Das spielt keine Rolle. Ich werde mich später um euch kümmern.',
    ('Text/Event/Miyako/Ekken.csvtxt', 'English#c:04010501_8'): 'Prinzessin Kokorowa spricht die Wahrheit.\nWelcher Art ist der Reis,\nden du verteilt hast?',
    ('Text/Event/Miyako/Ekken.csvtxt', 'English#c:04010501_9'): 'Alles ist... wie Prinzessin Sakuna sagt, meine Herrin.',
    ('Text/Event/Miyako/Ekken.csvtxt', 'English#c:06000501_0'): 'Prinzessin Sakuna. Prinzessin Kokorowa.\nIch höre, ihr wünscht euch die Verwandlungskugel.',
    ('Text/Event/Miyako/Ekken.csvtxt', 'English#c:06000501_1'): 'Ja, jawohl!',
    ('Text/Event/Miyako/Ekken.csvtxt', 'English#c:06000501_10'): 'Haha! Das ist ein Grund zum Feiern!',
    ('Text/Event/Miyako/Ekken.csvtxt', 'English#c:06000501_11'): 'Aber es gibt etwas, das zuerst getan werden muss.',
    ('Text/Event/Miyako/Ekken.csvtxt', 'English#c:06000501_12'): 'Genau der Ast, der die Verwandlungskugel\nträgt, wimmelt in letzter Zeit von\nInsekten.',
    ('Text/Event/Miyako/Ekken.csvtxt', 'English#c:06000501_13'): 'Insekten... sagst du?',
    ('Text/Event/Miyako/Ekken.csvtxt', 'English#c:06000501_14'): 'In der Tat Insekten. Genauer gesagt Blattläuse.',
    ('Text/Event/Miyako/Ekken.csvtxt', 'English#c:06000501_15'): 'Wenn du die Kugel willst, musst du zuerst\ndiesen unziemlichen Befall auslöschen!',
    ('Text/Event/Miyako/Ekken.csvtxt', 'English#c:06000501_16'): 'Blattläuse?!',
    ('Text/Event/Miyako/Ekken.csvtxt', 'English#c:06000501_2'): 'Es ist die Frucht, die an den Ästen\ndes Baums der Schöpfung reift, dem Wesen, aus dem\nich stamme und das diese Hauptstadt trägt.',
    ('Text/Event/Miyako/Ekken.csvtxt', 'English#c:06000501_3'): 'Weil sie eine allmächtige Kraft in so\neine kleine Form verdichtet, können wenige sie beherrschen.\nIch erlaube niemandem, sie ohne meine Genehmigung zu haben.',
    ('Text/Event/Miyako/Ekken.csvtxt', 'English#c:06000501_4'): 'Was genau beabsichtigst du damit zu tun?',
    ('Text/Event/Miyako/Ekken.csvtxt', 'English#c:06000501_5'): 'Unseren Reis auf neue Höhen heben!',
    ('Text/Event/Miyako/Ekken.csvtxt', 'English#c:06000501_6'): 'Ich bitte dich, leih mir die Verwandlungskugel,\ndamit ich noch köstlichere Verehrte Ähren\nhervorbringen kann, deiner Göttlichkeit würdig!',
    ('Text/Event/Miyako/Ekken.csvtxt', 'English#c:06000501_7'): 'Hahahaha! Reis?! Du willst deinen Reis verbessern?!',
    ('Text/Event/Miyako/Ekken.csvtxt', 'English#c:06000501_8'): 'Ahahahaha! Du bist der Erste, der die\nVerwandlungskugel zu solch einem Zweck begehrt!',
    ('Text/Event/Miyako/Ekken.csvtxt', 'English#c:06000501_9'): 'Es interessiert mich. Ich möchte wissen, was eure\nBemühungen hervorbringen. Die Kugel steht dir zur Nutzung!',
    ('Text/Event/Miyako/Ekken.csvtxt', 'English#c:98000401_0'): 'Prinzessin Sakuna.',
    ('Text/Event/Miyako/Ekken.csvtxt', 'English#c:98000401_1'): 'J-Ja...',
    ('Text/Event/Miyako/Ekken.csvtxt', 'English#c:98000401_10'): 'Ich bin Katsura Uemon-no-jou Takamori.\nDie Leute nennen mich Tauemon.',
    ('Text/Event/Miyako/Ekken.csvtxt', 'English#c:98000401_11'): 'Ich bin Kinta! Wer bist du,\nder Chef oder so?',
    ('Text/Event/Miyako/Ekken.csvtxt', 'English#c:98000401_12'): 'Ich bin Yui. Mir gefällt es hier nicht.\nBitte schick uns nach Hause.',
    ('Text/Event/Miyako/Ekken.csvtxt', 'English#c:98000401_13'): 'Ich bin Myrthe, und das hier ist...',
    ('Text/Event/Miyako/Ekken.csvtxt', 'English#c:98000401_14'): 'Ah!',
    ('Text/Event/Miyako/Ekken.csvtxt', 'English#c:98000401_15'): '...Kaimaru!',
    ('Text/Event/Miyako/Ekken.csvtxt', 'English#c:98000401_16'): 'Wir Götter und ihr Menschen stammt aus zwei Reichen.\nDas heißt, die natürliche Ordnung trennt uns\nzwischen Erhabenem Reich und Niedrigem Reich.',
    ('Text/Event/Miyako/Ekken.csvtxt', 'English#c:98000401_17'): 'Dennoch ist die schwebende Brücke des Himmels,\ndie ihr überquert habt, bereits verschwunden.',
    ('Text/Event/Miyako/Ekken.csvtxt', 'English#c:98000401_18'): 'Selbst ich, die überragende Göttin Kamuhitsuki,\nweiß nicht, wann sie wieder erscheinen wird.',
    ('Text/Event/Miyako/Ekken.csvtxt', 'English#c:98000401_19'): 'Deshalb, bis dahin, helft ihr Prinzessin Sakuna,\ndie Unordnung zu beseitigen, die durch euer\nTreiben zurückblieb.',
    ('Text/Event/Miyako/Ekken.csvtxt', 'English#c:98000401_2'): 'Du bist mit Gunst gesegnt als Tochter\ndes großen Kriegsgottes Takeribi. Und dennoch...',
    ('Text/Event/Miyako/Ekken.csvtxt', 'English#c:98000401_20'): '„Beseitigen", bedeutet...?',
    ('Text/Event/Miyako/Ekken.csvtxt', 'English#c:98000401_21'): 'Prinzessin Sakuna.\nErinnerst du dich an die Insel der Dämonen?',
    ('Text/Event/Miyako/Ekken.csvtxt', 'English#c:98000401_22'): 'Es ist die abgelegene Insel, auf der sich deine\nEltern trafen und den bösen Gott Omizuchi besiegten.',
    ('Text/Event/Miyako/Ekken.csvtxt', 'English#c:98000401_23'): 'Jenes unruhige Land ist schon lange ein Nest der\nDämonen und steht noch immer nicht unter meiner Kontrolle.',
    ('Text/Event/Miyako/Ekken.csvtxt', 'English#c:98000401_24'): 'Ihr habt den Ursprung der unaufhörlichen Horde\nvon Dämonen zu untersuchen,\nwährend ihr sie von der Insel vertreibt.',
    ('Text/Event/Miyako/Ekken.csvtxt', 'English#c:98000401_25'): 'A-Aber das ist...',
    ('Text/Event/Miyako/Ekken.csvtxt', 'English#c:98000401_26'): 'Ich bitte um Nachsicht, Lady Kamuhitsuki, aber die\nInsel der Dämonen ist viel zu weit entfernt.\nAllein dauert es Tage, sie zu erreichen.',
    ('Text/Event/Miyako/Ekken.csvtxt', 'English#c:98000401_27'): 'Und? Hast du erwartet, von hier aus zu pendeln?\nDu wirst dir einen Stützpunkt auf der Insel schaffen\nund deine Befehle von dort aus erledigen.',
    ('Text/Event/Miyako/Ekken.csvtxt', 'English#c:98000401_28'): 'Bis dahin seid ihr aus der Hauptstadt verbannt!',
    ('Text/Event/Miyako/Ekken.csvtxt', 'English#c:98000401_29'): 'Waaaaaah!',
    ('Text/Event/Miyako/Ekken.csvtxt', 'English#c:98000401_3'): 'Du hast den göttlichen Speicher vernichtet,\nsamt den Opfergaben, die ich hätte empfangen sollen.',
    ('Text/Event/Miyako/Ekken.csvtxt', 'English#c:98000401_30'): 'Ihr... verbannt uns? Wirklich?',
    ('Text/Event/Miyako/Ekken.csvtxt', 'English#c:98000401_31'): 'Mein Wort ist Gesetz.\nDas ist alles. Nun geht.',
    ('Text/Event/Miyako/Ekken.csvtxt', 'English#c:98000401_32'): 'V-V-Verbannt...',
    ('Text/Event/Miyako/Ekken.csvtxt', 'English#c:98000401_33'): 'Komm, Prinzessin. Lass uns gehen.',
    ('Text/Event/Miyako/Ekken.csvtxt', 'English#c:98000401_4'): 'Wehe! Was hast du da getan?',
    ('Text/Event/Miyako/Ekken.csvtxt', 'English#c:98000401_5'): 'Ich... ich... *schnief*\nBitte... vergib mir.',
    ('Text/Event/Miyako/Ekken.csvtxt', 'English#c:98000401_6'): 'Es war alles... ihre Schuld... *schnief*',
    ('Text/Event/Miyako/Ekken.csvtxt', 'English#c:98000401_7'): 'Ein Gott darf die Verbrechen der Menschen nicht auf sie schieben!',
    ('Text/Event/Miyako/Ekken.csvtxt', 'English#c:98000401_8'): '*jammert* Es tut mir sooo leiiiiid!',
    ('Text/Event/Miyako/Ekken.csvtxt', 'English#c:98000401_9'): 'Nun denn... Kinder der Menschen.\nStellt euch vor.',
    ('Text/Event/Miyako/Ekken.csvtxt', 'English#c:Aburamushi_Begin_Choice'): 'Wirst du Blattläuse auslöschen?',
    ('Text/Event/Miyako/Ekken.csvtxt', 'English#c:Result_NoReward_0'): 'Hm? Du scheinst nicht viel erreicht zu haben.',
    ('Text/Event/Miyako/Ekken.csvtxt', 'English#c:Result_NoReward_1'): 'Ich werde dich erneut um deine Hilfe bitten. Ihr dürft treten.',
    ('Text/Event/Miyako/Ekken.csvtxt', 'English#c:Result_Reward_0'): 'Großartige Arbeit.',
    ('Text/Event/Miyako/Ekken.csvtxt', 'English#c:Result_Reward_1'): 'Ich werde dich erneut um deine Hilfe bitten. Ihr dürft treten.',
    ('Text/Event/Miyako/Ekken.csvtxt', 'English#c:Visit_0'): 'Es ist eine Freude, dich zu sehen, Prinzessin Sakuna.\nIch freue mich sehr auf deine Verehrten Ähren.',
    ('Text/Event/Miyako/Ekken.csvtxt', 'English#c:Visit_1'): 'Ah ja, würdest du in meinem Namen noch mehr Blattläuse auslöschen?\nIch habe verschiedene Belohnungen für dich, je nach deinem Erfolg.',
}

